CREATE TABLE campaign_run(id VARCHAR(64) PRIMARY KEY,plan_id VARCHAR(64) NOT NULL,audience_calculation_id BIGINT NOT NULL,audience_batch INT NOT NULL,status VARCHAR(32) NOT NULL,total_users INT NOT NULL,started_at TIMESTAMP(6) NOT NULL);
CREATE TABLE user_journey(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,started_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_run_user UNIQUE(run_id,user_id));
CREATE TABLE node_execution(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,node_key VARCHAR(64) NOT NULL,node_type VARCHAR(32) NOT NULL,result VARCHAR(255),branch_label VARCHAR(32),executed_at TIMESTAMP(6) NOT NULL,resume_at TIMESTAMP(6));
CREATE TABLE channel_receipt(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,node_key VARCHAR(64) NOT NULL,channel VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(6) NOT NULL);
